import pathlib,json,statistics
P=pathlib.Path;D=P('docs/tasks/carousel-discovery-2026-11-05');a=json.loads((D/'live-ttfb.json').read_bytes());fresh=json.loads((D/'live-fresh-connections.json').read_bytes())
lines=['# Separate read-only staging TTFB evidence','','Nine browser samples used cold HTTP cache but a connection pool already authenticated on robots.txt. Zero DNS/TCP/TLS Navigation Timing values therefore describe reused connections, not free connection setup. The browser, viewport, actual LCP element, complete timing entries and noindex result are in [live-ttfb.json](live-ttfb.json). No infrastructure/backend change was made.','','| Page | Response-wait min / median / max ms | Document TTFB median ms |','| --- | --- | ---: |']
for route in ['/ru/product/56','/ru/catalog','/ru']:
 rows=[r for r in a['results'] if r['route']==route];v=[r['parts']['serverWait'] for r in rows]
 lines.append(f"| {route} | {min(v):.1f} / {statistics.median(v):.1f} / {max(v):.1f} | {statistics.median(r['parts']['documentTtfb'] for r in rows):.1f} |")
lines+=['','Browser request-start delay was 0.8–1.7ms; observed HTML download was 1.4–391.6ms and image LCP render-after-load was 13.0–92.8ms. All nine pages retained `noindex, nofollow`. The large response-wait variation remains unresolved: it can include network, edge, SSR/backend/data dependencies, and cannot be assigned to backend computation from these client samples alone.','', 'Three additional curl processes created fresh TCP/TLS connections. Values below are phase differences, not cumulative curl timestamps; the OS may still cache DNS. These are separate samples, not a controlled browser before/after.','','| Page | DNS ms | TCP before TLS ms | TLS ms | Wait after pretransfer ms | Download ms |','| --- | ---: | ---: | ---: | ---: | ---: |']
for r in fresh['results']:
 lines.append(f"| {r['route']} | {r['dns']*1000:.1f} | {(r['connect']-r['dns'])*1000:.1f} | {(r['tls']-r['connect'])*1000:.1f} | {(r['ttfb']-r['pretransfer'])*1000:.1f} | {(r['total']-r['ttfb'])*1000:.1f} |")
lines+=['','The local fixture buffers SSR responses through a loopback relay and has frozen in-process API data. Its document TTFB/LCP cannot be used as deployed staging timings. A separate investigation should correlate repeated live client timings with existing edge/application request timing before proposing any cache, backend, Nginx or infrastructure change. Such changes are outside this task.','']
(D/'TTFB.md').write_text('\n'.join(lines),encoding='utf8');print('Wrote separate live timing report')
